import numpy as np
from sklearn.kernel_ridge import KernelRidge
from sklearn.linear_model import Ridge

class TravelTimeKRR:
    def __init__(self, floor=0.003, alpha=1e-3, gamma_mult=1.0, linear=False, target='invsqrt'):
        self.floor = floor
        self.alpha = alpha
        self.gamma_mult = gamma_mult
        self.linear = linear
        self.target = target

    def _feat(self, X):
        Z = np.log(np.maximum(np.asarray(X, dtype=float), self.floor))
        return (Z - self.mu) / self.sd

    def _fwd(self, y):
        y = np.clip(np.asarray(y, dtype=float), 1e-3, None)
        return y ** -0.5 if self.target == 'invsqrt' else np.log(y)

    def _inv(self, z):
        if self.target == 'invsqrt':
            k = 1.0 / np.maximum(z, 1e-3) ** 2
        else:
            k = np.exp(z)
        return np.clip(k, 0.5, 2.0)

    def fit(self, X, y):
        Z = np.log(np.maximum(np.asarray(X, dtype=float), self.floor))
        self.mu = Z.mean(0)
        self.sd = Z.std(0) + 1e-8
        F = (Z - self.mu) / self.sd
        T = self._fwd(y)
        self.tm = T.mean(0)
        if self.linear:
            self.m = Ridge(alpha=self.alpha)
        else:
            g = self.gamma_mult / (F.shape[1] * max(F.var(), 1e-12))
            self.m = KernelRidge(alpha=self.alpha, kernel='rbf', gamma=g)
        self.m.fit(F, T - self.tm)
        return self

    def predict(self, X):
        return self._inv(self.m.predict(self._feat(X)) + self.tm)

def build_model(params, task, seed):
    return TravelTimeKRR(
        floor=params.get('floor', 0.003),
        alpha=params.get('alpha', 1e-3),
        gamma_mult=params.get('gamma_mult', 1.0),
        linear=params.get('linear', False),
        target=params.get('target', 'invsqrt'),
    )
